//! The reference client's icon set, compiled into strokeable geometry.
//!
//! **Generated by `tools/gen_icons.py`. Do not edit.**
//!
//! These are the Modrinth App's own icons, out of the 313 SVGs in
//! `vendor/modrinth-app/assets/icons`, and they are outlines rather than
//! pictures: the reference draws them stroked in `currentColor` at width 2
//! with round caps and joins, which is what lets an icon take the colour of
//! the control it sits in. This is why they are geometry and not a bitmap --
//! a rasterised icon cannot be tinted, and the shell's previous icons were
//! bitmaps carved out of another launcher's binary.
//!
//! Arcs, quadratics and the smooth-curve commands are all already converted
//! to cubics by the generator, and `<g transform>` is applied to every point
//! before it is written: an affine map commutes with Bezier evaluation, so
//! transforming the control points transforms the curve exactly.
//!
//! Gate: `python tools/gen_icons.py --check` regenerates and compares bytes.

// Nothing draws these yet: the shell that will is stage 2 of
// `docs/superpowers/specs/2026-09-24-modrinth-native-rewrite.md`, and the shell
// on screen today draws `crate::icons`' carved PNGs. Delete this line the day
// the last icon is drawn from here.
#![allow(dead_code)]

use iced::widget::canvas::{LineCap, LineDash, LineJoin, Path, Stroke, Style};
use iced::{Color, Point};

/// One drawing step. Absolute coordinates, in the icon's own view box.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Cmd {
    /// Start a subpath at `(x, y)`.
    Move(f32, f32),
    /// A straight line to `(x, y)`.
    Line(f32, f32),
    /// A cubic Bezier: two control points then the end point.
    Cubic(f32, f32, f32, f32, f32, f32),
    /// Close the current subpath.
    Close,
}

/// Where an element's colour comes from.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Ink {
    /// `currentColor`: the colour of whatever the icon is drawn in, which is
    /// what almost every icon in the set asks for.
    Inherit,
    /// A literal the reference wrote out: a red, a white.
    Fixed(u8, u8, u8, u8),
    /// A `var(--token)` the reference names, to be resolved through
    /// `crate::theme_gen` rather than guessed at here.
    Token(&'static str),
}

impl Ink {
    /// The colour this element is, given what the caller is drawing with.
    pub fn resolve(self, inherit: Color) -> Color {
        match self {
            Ink::Inherit => inherit,
            Ink::Fixed(r, g, b, a) => Color::from_rgba8(r, g, b, a as f32 / 255.0),
            // A token the shell has not been taught yet is drawn in the ink it
            // would have had anyway, which is visible rather than invisible.
            Ink::Token(_) => inherit,
        }
    }
}

/// One drawable piece of an icon: geometry, and how to paint it.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Element {
    /// The geometry, in the icon's view box.
    pub commands: &'static [Cmd],
    /// Stroke width, in view-box units.
    pub stroke_width: f32,
    /// Whether this element is filled rather than stroked.
    pub filled: bool,
    /// Where its colour comes from.
    pub ink: Ink,
    /// The element's own `opacity`, which multiplies whatever ink it gets.
    ///
    /// The spinner's ring is a quarter opaque, so this is not decoration:
    /// a stroke at full opacity there draws a solid ring instead of a track.
    pub opacity: f32,
}

